package com.secureauth.ldap

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import javax.naming.directory.{InitialDirContext, SearchControls, SearchResult}
import javax.naming.{Context, NamingEnumeration}
import java.util.Hashtable
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Cipher
import javax.crypto.spec.{SecretKeySpec, IvParameterSpec}

object CryptoConfig {
  val AES_KEY: Array[Byte] = "0123456789abcdef0123456789abcdef".getBytes("UTF-8").take(32)
  val AES_IV: Array[Byte] = "fedcba9876543210".getBytes("UTF-8").take(16)
}

trait LdapEncoder {
  def encodeForLdap(input: String): String
}

class Rfc2254Encoder extends LdapEncoder {
  private val ESCAPE_CHARS = Map(
    '\\' -> "\\5c",
    '*' -> "\\2a",
    '(' -> "\\28",
    ')' -> "\\29",
    '\u0000' -> "\\00"
  )

  override def encodeForLdap(input: String): String = {
    input.flatMap { c =>
      ESCAPE_CHARS.getOrElse(c, c.toString)
    }
  }
}

class CryptoTokenService {
  private def decrypt(encryptedToken: String): String = {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    val keySpec = new SecretKeySpec(CryptoConfig.AES_KEY, "AES")
    val ivSpec = new IvParameterSpec(CryptoConfig.AES_IV)
    cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec)
    val decoded = Base64.getDecoder.decode(encryptedToken)
    new String(cipher.doFinal(decoded), "UTF-8")
  }

  def extractUsername(encryptedToken: String): Future[String] = Future {
    val decrypted = decrypt(encryptedToken)
    val parts = decrypted.split("\\|")
    if (parts.length >= 3) {
      val timestamp = parts(0).toLong
      val nonce = parts(1)
      val username = parts(2)
      val currentTime = System.currentTimeMillis()
      if (currentTime - timestamp < 300000) username
      else throw new SecurityException("Token expired")
    } else throw new SecurityException("Invalid token format")
  }
}

class LdapAuthService(
  ldapUrl: String,
  baseDn: String,
  encoder: LdapEncoder,
  cryptoService: CryptoTokenService
) {

  private def buildSearchFilter(username: String, groupDn: String): String = {
    val sanitizedUser = encoder.encodeForLdap(username)
    s"(&(uid=$sanitizedUser)(memberOf=$groupDn))"
  }

  private def createContext(): InitialDirContext = {
    val env = new Hashtable[String, String]()
    env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory")
    env.put(Context.PROVIDER_URL, ldapUrl)
    env.put(Context.SECURITY_AUTHENTICATION, "simple")
    env.put(Context.SECURITY_PRINCIPAL, "cn=admin,dc=example,dc=com")
    env.put(Context.SECURITY_CREDENTIALS, "adminpass")
    new InitialDirContext(env)
  }

  def authenticateWithToken(
    encryptedToken: String,
    groupDn: String
  ): Future[Option[SearchResult]] = {
    cryptoService.extractUsername(encryptedToken).flatMap { username =>
      performLdapSearch(username, groupDn)
    }
  }

  private def performLdapSearch(
    username: String,
    groupDn: String
  ): Future[Option[SearchResult]] = Future {
    val ctx = createContext()
    try {
      val controls = new SearchControls()
      controls.setSearchScope(SearchControls.SUBTREE_SCOPE)
      controls.setReturningAttributes(Array("uid", "cn", "mail"))
      controls.setCountLimit(1)
      val filter = buildSearchFilter(username, groupDn)
      val results: NamingEnumeration[SearchResult] = ctx.search(baseDn, filter, controls)
      if (results.hasMore) Some(results.next()) else None
    } finally {
      ctx.close()
    }
  }
}

class AuthenticationController(authService: LdapAuthService) {

  def handleAuthRequest(
    encryptedToken: String,
    requestedGroup: String
  ): Future[Either[String, Map[String, String]]] = {
    authService.authenticateWithToken(encryptedToken, requestedGroup).map {
      case Some(result) =>
        val attrs = result.getAttributes
        Right(Map(
          "uid" -> attrs.get("uid").get().toString,
          "cn" -> attrs.get("cn").get().toString,
          "mail" -> attrs.get("mail").get().toString
        ))
      case None =>
        Left("Authentication failed")
    }.recover {
      case _: SecurityException => Left("Invalid or expired token")
      case _: Exception => Left("Internal error")
    }
  }
}
